  str_n5_battlefield_mission_name1 = "Desert Hunt",
  str_n5_battlefield_mission_name2 = "Desert Pursuit",
  str_n5_battlefield_mission_name3 = "Wasteland Strike",
  str_n5_battlefield_mission_name4 = "Highland Siege",
  str_n5_battlefield_mission_desc1 = "Although the desert is vast, we know it like the back of our hands. No matter how many Eclipsites escape into the depths of the desert, they are merely our prey, waiting to be culled.",
  str_n5_battlefield_mission_desc2 = "The terrain of this vast desert is indeed complex. The Eclipsites seek to ambush here and make their final stand, but their plan is nothing but a delusion.",
  str_n5_battlefield_mission_desc3 = "A single Eclipsite is nothing to be afraid of, but a swarm of Eclipsites poses a threat. If you encounter a mass of Eclipsites in the wasteland, make sure you can take them on, or try to avoid them altogether.",
  str_n5_battlefield_mission_desc4 = "The Eclipsites gather on the high ground to stage a last-ditch resistance. In encircling and attacking them, we're certain to incur losses, but if we do not face this problem head on, we will never have peace.",
  str_n5_battlefield_recommendDesc1 = "Ascension I Lv. 1—Ascension I Lv. 40",
